<script setup>
import { onMounted, ref } from 'vue'
import { apiOrigin } from '../services/auth.js'
const props = defineProps({ session: { type: Object, required: true } })
const dateParts = new Intl.DateTimeFormat('en', { timeZone: 'Europe/Kyiv', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date())
const part = name => dateParts.find(p => p.type === name).value
const today = `${part('year')}-${part('month')}-${part('day')}`
const from = ref(today.slice(0, 7) + '-01'), to = ref(today), branch = ref(''), branches = ref([]), data = ref(null), busy = ref(false), error = ref(''), applied = ref(null)
const money = value => value == null ? 'Не визначено' : Number(value).toLocaleString('uk-UA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
async function api(path) { const response = await fetch(`${apiOrigin}/api/reports/owner-results${path}`, { headers: { Authorization: `Bearer ${props.session.token}` } }); const result = await response.json().catch(() => null); if (!response.ok) throw new Error(result?.message || `Не вдалося завантажити звіт (HTTP ${response.status})`); return result }
async function load(page = 0, next = null) {
 if (busy.value) return
 const filter = next || applied.value || { from: from.value, to: to.value, branch: branch.value }
 if (!filter.from || !filter.to || filter.from > filter.to) { error.value = 'Перевірте початок і кінець періоду.'; return }
 busy.value = true; error.value = ''; data.value = null
 try { const query = new URLSearchParams({ from: filter.from, to: filter.to, page: String(page) }); if (filter.branch) query.set('branch', filter.branch); data.value = await api('?' + query); applied.value = { ...filter } } catch (e) { error.value = e.message } finally { busy.value = false }
}
function apply() { return load(0, { from: from.value, to: to.value, branch: branch.value }) }
onMounted(async () => { try { branches.value = await api('/branches'); await apply() } catch (e) { error.value = e.message } })
</script>
<template>
 <section class="owner-results">
  <h1>Результати роботи</h1><p>Власні філії · за першою підтвердженою видачею клієнту · доступно адміністратору.</p>
  <form class="report-filters" @submit.prevent="apply"><label>Від<input v-model="from" type="date" :disabled="busy" required></label><label>До включно<input v-model="to" type="date" :disabled="busy" required></label><label>Філія<select v-model="branch" :disabled="busy"><option value="">Усі власні філії</option><option v-for="b in branches" :key="b.id" :value="String(b.id)">{{ b.name }}</option></select></label><button :disabled="busy">Показати</button></form>
  <p v-if="error" role="alert">{{ error }}</p><p v-if="busy">Формування звіту…</p>
  <template v-if="data">
   <p>Період звіту: {{ data.from }} — {{ data.to }} · {{ branches.find(b => String(b.id) === applied.branch)?.name || 'Усі власні філії' }}. Підсумки охоплюють усі сторінки.</p>
   <div class="report-metrics"><article><span>Виданих карток виробів</span><strong>{{ data.summary.productCount }}</strong></article><article><span>{{ data.summary.unknownSales ? 'Відома вартість видач' : 'Вартість видач' }}</span><strong>{{ money(data.summary.knownSales) }} грн</strong></article><article><span>{{ data.summary.unknownMaterials ? 'Відома частина матеріалів' : 'Закупівельні витрати матеріалів' }}</span><strong>{{ money(data.summary.knownMaterials) }} грн</strong></article><article><span>Нарахована винагорода</span><strong>{{ money(data.summary.rewards) }} грн</strong></article><article><span>Різниця після матеріалів і винагороди</span><strong>{{ money(data.summary.difference) }}{{ data.summary.difference == null ? '' : ' грн' }}</strong></article></div>
   <p v-if="data.summary.incompleteCount" class="report-warning">Неповні дані для {{ data.summary.incompleteCount }} карток: сума продажу невідома — {{ data.summary.unknownSales }}, матеріали не повністю оцінені — {{ data.summary.unknownMaterials }}, винагорода потребує уточнення — {{ data.summary.pendingRewards }}. Різниця лише за повністю оціненими картками: {{ money(data.summary.completeDifference) }} грн.</p>
   <details><summary>Як читати звіт</summary><p>Картка може містити кілька однакових виробів: кількість карток не дорівнює кількості фізичних одиниць. Повторна видача не рахується повторно. Видачі без записаної події приймання клієнтом не відновлюються зі статусів.</p><p>Вартість продажу береться зі збереженої суми виробу в чинному рахунку. Старий загальний рахунок без розподілу за виробами не розподіляється довільно. Матеріали — зі списань до першої видачі, включно з доопрацюваннями до неї. Старі невідомі ціни не замінюються поточними.</p><p>Винагорода — фактичні нарахування за ці вироби з усіма поточними коригуваннями; виплати менеджерам не віднімаються вдруге. Якщо нарахувань немає, показано 0; ставка заднім числом не застосовується. Через коригування результат минулого періоду може змінитися.</p><p>Різниця не є чистим прибутком: зарплата майстерні, оренда та інші витрати не враховані. Це звіт видач, а не чистих продажів після повернень. Надходження коштів, аванси, борги й розрахунки посередників сюди не входять.</p></details>
   <p v-if="!data.rows.length">Видач за вибраними умовами немає.</p>
   <div class="results-list"><article v-for="row in data.rows" :key="row.productId" class="result-row"><header><strong>Замовлення № {{ row.orderNo }} · {{ row.productName }}</strong><span>{{ row.branchName }} · {{ row.issuedAt }}</span></header><dl><div><dt>Вартість видачі</dt><dd>{{ money(row.saleAmount) }}</dd></div><div><dt>{{ row.unknownMaterials ? 'Матеріали (відома частина)' : 'Матеріали' }}</dt><dd>{{ money(row.materialAmount) }}</dd></div><div><dt>Винагорода</dt><dd>{{ money(row.rewardAmount) }}{{ row.rewardState === 'REVIEW' ? ' · потребує уточнення' : '' }}</dd></div><div><dt>Різниця, грн</dt><dd>{{ money(row.difference) }}</dd></div></dl><p v-if="row.unknownMaterials">Неоцінених позицій матеріалів: {{ row.unknownMaterials }}</p></article></div>
   <div class="report-paging"><button :disabled="busy || data.page === 0" @click="load(data.page - 1)">Назад</button><span>Сторінка {{ data.page + 1 }}</span><button :disabled="busy || !data.hasMore" @click="load(data.page + 1)">Далі</button></div>
  </template>
 </section>
</template>
<style scoped>
.owner-results{max-width:1250px;margin:auto;padding:20px;color:#233442;min-width:0}.owner-results h1{margin:0 0 10px}.owner-results p{line-height:1.5}.report-filters{display:grid;grid-template-columns:1fr 1fr 2fr auto;gap:12px;align-items:end;margin:20px 0}.report-filters label{display:grid;gap:6px;min-width:0}.owner-results input,.owner-results select,.owner-results button{box-sizing:border-box;max-width:100%;min-width:0;font:inherit;padding:10px;border:1px solid #bdccd4;border-radius:7px;min-height:44px}.owner-results button{cursor:pointer;background:#185c63;color:white}.owner-results button:disabled{opacity:.5}.report-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.report-metrics article{padding:16px;border-radius:10px;background:#eef5f6;overflow-wrap:anywhere}.report-metrics span{font-size:13px}.report-metrics strong{display:block;margin-top:10px;font-size:21px}.report-warning{padding:12px;background:#fff4d5;border-radius:8px}.owner-results details{margin:20px 0}.owner-results summary{cursor:pointer}.result-row{padding:16px;border:1px solid #dce4e9;border-radius:10px;margin:12px 0}.result-row header{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.result-row header span{font-size:13px;color:#617580}.result-row dl{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.result-row dt{font-size:13px}.result-row dd{margin:6px 0 0;font-weight:600;overflow-wrap:anywhere}.report-paging{display:flex;align-items:center;gap:12px}[role=alert]{color:#a22}@media(max-width:700px){.owner-results{padding:12px}.report-filters{grid-template-columns:1fr 1fr}.report-filters label:nth-child(3){grid-column:1/-1}.report-filters button{grid-column:1/-1}.result-row dl{grid-template-columns:1fr 1fr}.report-metrics{grid-template-columns:1fr 1fr}.report-metrics article:last-child{grid-column:1/-1}}
</style>
